-- Estrutura Giro63. Aplicar uma única vez pelo processo de migração.
-- Todas as tabelas permanecem em schema privado sem permissões para anon/authenticated.
BEGIN;
CREATE SCHEMA IF NOT EXISTS giro63;
REVOKE ALL ON SCHEMA giro63 FROM PUBLIC, anon, authenticated;
CREATE TABLE giro63.users (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL, email text NOT NULL, password text NOT NULL, role text NOT NULL CHECK (role IN ('author','editor')), active integer NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX users_email_lower ON giro63.users (lower(email));
CREATE TABLE giro63.editorial_categories (slug text PRIMARY KEY, name text NOT NULL, position integer NOT NULL DEFAULT 0, show_menu integer NOT NULL DEFAULT 1);
CREATE TABLE giro63.settings (key text PRIMARY KEY, value text NOT NULL);
CREATE TABLE giro63.articles (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, slug text NOT NULL UNIQUE, title text NOT NULL, summary text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', category text NOT NULL, city text NOT NULL DEFAULT '', author_id bigint REFERENCES giro63.users(id), byline text NOT NULL DEFAULT '', cover text NOT NULL DEFAULT '/images/cerrado.jpg', cover_alt text NOT NULL DEFAULT '', credit text NOT NULL DEFAULT '', sources text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','review','published')), featured integer NOT NULL DEFAULT 0, urgent integer NOT NULL DEFAULT 0, demo integer NOT NULL DEFAULT 0, feedback text NOT NULL DEFAULT '', created_at text NOT NULL, updated_at text NOT NULL, published_at text);
CREATE INDEX articles_public ON giro63.articles(status,published_at DESC);
CREATE INDEX articles_category ON giro63.articles(category,status);
CREATE TABLE giro63.ads (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL, advertiser text NOT NULL DEFAULT '', image text NOT NULL, alt text NOT NULL, link text NOT NULL DEFAULT '', position text NOT NULL CHECK(position IN ('top','middle','sidebar')), active integer NOT NULL DEFAULT 1, starts_at text, ends_at text, archived integer NOT NULL DEFAULT 0);
CREATE TABLE giro63.sessions (sid text PRIMARY KEY, data text NOT NULL, expires bigint NOT NULL);
CREATE INDEX sessions_expiry ON giro63.sessions(expires);
CREATE TABLE giro63.article_daily_reads (article_id bigint NOT NULL REFERENCES giro63.articles(id), day text NOT NULL, views integer NOT NULL DEFAULT 0, PRIMARY KEY(article_id,day));
CREATE INDEX article_reads_day ON giro63.article_daily_reads(day,article_id);
CREATE TABLE giro63.article_read_windows(session_hash text NOT NULL,article_id bigint NOT NULL REFERENCES giro63.articles(id),expires_at bigint NOT NULL,PRIMARY KEY(session_hash,article_id));
CREATE INDEX article_read_windows_expiry ON giro63.article_read_windows(expires_at);
CREATE TABLE giro63.ad_rotation (position text PRIMARY KEY, last_id bigint NOT NULL);
CREATE TABLE giro63.ad_deliveries (token text PRIMARY KEY, ad_id bigint NOT NULL REFERENCES giro63.ads(id), expires_at bigint NOT NULL, viewed integer NOT NULL DEFAULT 0, clicked integer NOT NULL DEFAULT 0);
CREATE INDEX ad_deliveries_expiry ON giro63.ad_deliveries(expires_at);
CREATE TABLE giro63.ad_daily (ad_id bigint NOT NULL REFERENCES giro63.ads(id), day text NOT NULL, impressions integer NOT NULL DEFAULT 0, clicks integer NOT NULL DEFAULT 0, PRIMARY KEY(ad_id,day));
CREATE TABLE giro63.audience_daily (day text NOT NULL, path text NOT NULL, views integer NOT NULL DEFAULT 0, PRIMARY KEY(day,path));
CREATE TABLE giro63.audience_deliveries (token_hash text PRIMARY KEY, path text NOT NULL, expires_at bigint NOT NULL, used integer NOT NULL DEFAULT 0);
CREATE INDEX audience_deliveries_expiry ON giro63.audience_deliveries(expires_at);
CREATE TABLE giro63.login_attempts (key_hash text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, expires_at bigint NOT NULL);
CREATE INDEX login_attempts_expiry ON giro63.login_attempts(expires_at);
CREATE INDEX articles_author ON giro63.articles(author_id);
CREATE INDEX ad_deliveries_ad ON giro63.ad_deliveries(ad_id);
CREATE FUNCTION giro63.normalize_search(value text) RETURNS text LANGUAGE sql IMMUTABLE STRICT SET search_path='' AS $$
  SELECT translate(lower(value), 'áàâãäåéèêëíìîïóòôõöúùûüçñ', 'aaaaaaeeeeiiiiooooouuuucn')
$$;
REVOKE ALL ON ALL TABLES IN SCHEMA giro63 FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA giro63 FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA giro63 FROM PUBLIC, anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA giro63 REVOKE ALL ON TABLES FROM PUBLIC, anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA giro63 REVOKE ALL ON SEQUENCES FROM PUBLIC, anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA giro63 REVOKE ALL ON FUNCTIONS FROM PUBLIC, anon, authenticated;
COMMIT;


CREATE TABLE IF NOT EXISTS giro63.tags(slug TEXT PRIMARY KEY,name TEXT NOT NULL,normalized TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS giro63.article_tags(article_id BIGINT NOT NULL REFERENCES giro63.articles(id),tag_slug TEXT NOT NULL REFERENCES giro63.tags(slug),PRIMARY KEY(article_id,tag_slug));
CREATE TABLE IF NOT EXISTS giro63.automation_sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,website TEXT NOT NULL,feed TEXT NOT NULL DEFAULT '',hosts TEXT NOT NULL,permission_note TEXT NOT NULL DEFAULT '',approved INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 0,region TEXT NOT NULL DEFAULT 'national',last_error TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS giro63.automation_items(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES giro63.automation_sources(id),uid TEXT NOT NULL,url TEXT NOT NULL,title TEXT NOT NULL,summary TEXT NOT NULL,fingerprint TEXT NOT NULL,original_at TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,article_id BIGINT REFERENCES giro63.articles(id),note TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL,UNIQUE(source_id,uid),UNIQUE(url));
CREATE INDEX IF NOT EXISTS automation_queue ON giro63.automation_items(state,original_at);
CREATE INDEX IF NOT EXISTS automation_fingerprint ON giro63.automation_items(fingerprint);
CREATE TABLE IF NOT EXISTS giro63.automation_daily(day TEXT PRIMARY KEY,calls INTEGER NOT NULL DEFAULT 0,published INTEGER NOT NULL DEFAULT 0,national INTEGER NOT NULL DEFAULT 0,input_tokens INTEGER NOT NULL DEFAULT 0,output_tokens INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS giro63.automation_lock(id TEXT PRIMARY KEY,owner TEXT NOT NULL,expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS giro63.automation_events(id TEXT PRIMARY KEY,created_at TEXT NOT NULL,message TEXT NOT NULL);

REVOKE ALL ON ALL TABLES IN SCHEMA giro63 FROM PUBLIC,anon,authenticated;
